<?php require_once __DIR__.'/../model/auth_model.php';$m=new AuthModel();$action=$_GET['action']??'login';$error='';$success='';if($action==='logout'){session_destroy();header('Location:index.php?action=login');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){if($action==='login'){$u=$m->byEmail(trim($_POST['email']??''));if($u&&password_verify($_POST['password']??'',$u['password'])){$_SESSION['user']=['id'=>(int)$u['id'],'name'=>$u['name'],'email'=>$u['email'],'role'=>$u['role']];header('Location:index.php?action=dashboard');exit;}$error='Invalid email or password.';}else{$n=trim($_POST['name']??'');$e=trim($_POST['email']??'');$p=trim($_POST['phone']??'');$pw=$_POST['password']??'';$cp=$_POST['confirm_password']??'';if(!$n||!filter_var($e,FILTER_VALIDATE_EMAIL)||!$p||strlen($pw)<6||$pw!==$cp)$error='Please complete all fields correctly.';elseif($m->byEmail($e))$error='Email already exists.';else{$m->register($n,$e,$p,$pw);$success='Registration successful. Please login.';$action='login';}}}require __DIR__.'/../views/'.($action==='register'?'register':'login').'.php';?>